package com.combatglance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

public class AttackCycleTrackerTest
{
	private AttackCycleTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new AttackCycleTracker();
	}

	@Test
	public void unknownUntilSpeedAndAnchorAreBothSet()
	{
		assertFalse(tracker.isKnown());
		tracker.setWeaponSpeed(4);
		assertFalse(tracker.isKnown());
		tracker.noteEngagement(10, "goblin#1");
		assertTrue(tracker.isKnown());
	}

	@Test
	public void freeRunsFromTheEngagementAnchorAtTheKnownSpeed()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(10, "goblin#1");

		assertEquals(3, tracker.ticksUntilReady(10));
		assertEquals(2, tracker.ticksUntilReady(11));
		assertEquals(0, tracker.ticksUntilReady(13));
		assertEquals(3, tracker.ticksUntilReady(14));
		assertEquals(2, tracker.ticksUntilReady(15));
	}

	@Test
	public void doesNotRequireReconfirmingEveryIndividualAttack()
	{
		// This is the whole point of the redesign: once speed + anchor are known, the cycle
		// keeps counting correctly on its own, even if onAttackObserved is never called again —
		// unlike the old design, which required a fresh, correctly-timed observation every
		// single attack just to keep showing anything.
		tracker.setWeaponSpeed(5);
		tracker.noteEngagement(0, "goblin#1");

		for (int cycle = 0; cycle < 20; cycle++)
		{
			// Last waiting tick of each cycle — the bar should read fully ready right before the
			// next attack fires, not on the (ambiguous) boundary tick shared with the next cycle.
			long tick = (long) cycle * 5 + 4;
			assertEquals("cycle " + cycle, 0, tracker.ticksUntilReady(tick));
		}
	}

	@Test
	public void observedAttackReanchorsToSelfCorrectDrift()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(0, "goblin#1");
		// Real cadence turns out to be 1 tick faster than the estimate (e.g. a style speed
		// modifier) — the observation re-anchors rather than being rejected as "impossible".
		tracker.onAttackObserved(3);

		assertEquals(3, tracker.ticksUntilReady(3));
		assertEquals(2, tracker.ticksUntilReady(4));
	}

	@Test
	public void weaponChangeClearsTheAnchorUntilTheNextEngagement()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(0, "goblin#1");
		assertTrue(tracker.isKnown());

		tracker.setWeaponSpeed(5);
		assertFalse(tracker.isKnown());

		tracker.noteEngagement(10, "goblin#1");
		assertTrue(tracker.isKnown());
		assertEquals(4, tracker.ticksUntilReady(10));
	}

	@Test
	public void sameWeaponSpeedPushedAgainDoesNotResetTheAnchor()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(0, "goblin#1");
		tracker.setWeaponSpeed(4);
		assertEquals(1, tracker.ticksUntilReady(2));
	}

	@Test
	public void targetChangeReanchorsCleanly()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(0, "goblin#1");
		tracker.noteEngagement(2, "goblin#1");
		assertEquals(1, tracker.ticksUntilReady(2));

		tracker.noteEngagement(2, "cow#2");
		assertEquals(3, tracker.ticksUntilReady(2));
	}

	@Test
	public void unknownSpeedHidesReadinessRatherThanGuessing()
	{
		tracker.noteEngagement(0, "goblin#1");
		assertFalse(tracker.isKnown());
		assertEquals(-1, tracker.ticksUntilReady(1));
		assertEquals(-1.0, tracker.elapsedFraction(1), 0.0001);
	}

	@Test
	public void resetOnInactivityClearsSpeedAndAnchor()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(0, "goblin#1");
		tracker.onTick(AttackCycleTracker.INACTIVITY_TIMEOUT_TICKS);

		assertFalse(tracker.isKnown());
	}

	@Test
	public void elapsedFractionTracksProgressThroughTheCycleAndFillsCompletelyOnTheFinalTick()
	{
		tracker.setWeaponSpeed(4);
		tracker.noteEngagement(0, "goblin#1");

		assertEquals(0.25, tracker.elapsedFraction(0), 0.0001);
		assertEquals(0.75, tracker.elapsedFraction(2), 0.0001);
		// Final waiting tick before the next attack fires — bar must read fully filled here, not
		// just short of it.
		assertEquals(1.0, tracker.elapsedFraction(3), 0.0001);
		assertEquals(0.25, tracker.elapsedFraction(4), 0.0001);
	}

	@Test
	public void invalidSpeedIsTreatedAsUnknown()
	{
		tracker.setWeaponSpeed(0);
		tracker.noteEngagement(0, "goblin#1");
		assertFalse(tracker.isKnown());

		tracker.setWeaponSpeed(999);
		assertFalse(tracker.isKnown());
	}
}

package com.combatglance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Prayer;
import org.junit.Test;

public class PrayerClassifierTest
{
	@Test
	public void combinedPrayersAreOffense()
	{
		assertEquals(PrayerKind.OFFENSE, PrayerClassifier.kindOf(Prayer.PIETY));
		assertEquals(PrayerKind.OFFENSE, PrayerClassifier.kindOf(Prayer.RIGOUR));
		assertEquals(PrayerKind.OFFENSE, PrayerClassifier.kindOf(Prayer.AUGURY));
	}

	@Test
	public void standardProtectPrayersAreOverhead()
	{
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.PROTECT_FROM_MELEE));
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.PROTECT_FROM_MISSILES));
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.PROTECT_FROM_MAGIC));
	}

	@Test
	public void ruinousDampenAndWrathAreOverhead()
	{
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.RP_DAMPEN_MAGIC));
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.RP_DAMPEN_RANGED));
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.RP_DAMPEN_MELEE));
		assertEquals(PrayerKind.OVERHEAD, PrayerClassifier.kindOf(Prayer.RP_WRATH));
	}

	@Test
	public void utilityAndSkinPrayersAreOther()
	{
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.THICK_SKIN));
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.ROCK_SKIN));
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.STEEL_SKIN));
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.RAPID_RESTORE));
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.RAPID_HEAL));
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.PROTECT_ITEM));
		assertEquals(PrayerKind.OTHER, PrayerClassifier.kindOf(Prayer.PRESERVE));
	}

	@Test
	public void primaryOffensePrefersCombinedOverSingleSkill()
	{
		Set<Prayer> active = EnumSet.of(Prayer.PIETY, Prayer.ULTIMATE_STRENGTH);
		assertEquals(Prayer.PIETY, PrayerClassifier.primaryOffense(active, CombatStyle.MELEE));
	}

	@Test
	public void primaryOffenseWithoutCombinedIsDeterministic()
	{
		Set<Prayer> active = EnumSet.of(Prayer.ULTIMATE_STRENGTH, Prayer.INCREDIBLE_REFLEXES);
		Prayer first = PrayerClassifier.primaryOffense(active, CombatStyle.MELEE);
		Prayer second = PrayerClassifier.primaryOffense(active, CombatStyle.MELEE);
		assertEquals(first, second);
		assertEquals(Prayer.ULTIMATE_STRENGTH, first);
	}

	@Test
	public void primaryOffensePrefersRigourForRangedStyleEvenIfMeleePrayerActive()
	{
		Set<Prayer> active = EnumSet.of(Prayer.PIETY, Prayer.RIGOUR);
		assertEquals(Prayer.RIGOUR, PrayerClassifier.primaryOffense(active, CombatStyle.RANGED));
	}

	@Test
	public void primaryOffenseFallsBackToAnyCombinedWhenStyleDoesNotMatch()
	{
		// Only a melee combined prayer is active while the style is ranged — no ranged
		// candidate exists, so step 2 (any remaining combined prayer) picks it up.
		Set<Prayer> active = EnumSet.of(Prayer.PIETY);
		assertEquals(Prayer.PIETY, PrayerClassifier.primaryOffense(active, CombatStyle.RANGED));
	}

	@Test
	public void noActiveOffenseReturnsNull()
	{
		assertNull(PrayerClassifier.primaryOffense(EnumSet.noneOf(Prayer.class), CombatStyle.MELEE));
	}

	@Test
	public void noActiveOverheadReturnsNull()
	{
		assertNull(PrayerClassifier.primaryOverhead(EnumSet.noneOf(Prayer.class)));
	}

	@Test
	public void primaryOverheadPicksTheSingleActiveOne()
	{
		Set<Prayer> active = EnumSet.of(Prayer.PROTECT_FROM_MELEE);
		assertEquals(Prayer.PROTECT_FROM_MELEE, PrayerClassifier.primaryOverhead(active));
	}

	@Test
	public void offenseSelectionIgnoresOtherAndOverheadPrayers()
	{
		Set<Prayer> active = EnumSet.of(Prayer.PROTECT_FROM_MELEE, Prayer.STEEL_SKIN, Prayer.PROTECT_ITEM);
		assertNull(PrayerClassifier.primaryOffense(active, CombatStyle.MELEE));
	}

	@Test
	public void styleOfMapsStandardOffensePrayersToOneStyle()
	{
		assertEquals(CombatStyle.MELEE, PrayerClassifier.styleOf(Prayer.PIETY));
		assertEquals(CombatStyle.MELEE, PrayerClassifier.styleOf(Prayer.ULTIMATE_STRENGTH));
		assertEquals(CombatStyle.RANGED, PrayerClassifier.styleOf(Prayer.RIGOUR));
		assertEquals(CombatStyle.RANGED, PrayerClassifier.styleOf(Prayer.EAGLE_EYE));
		assertEquals(CombatStyle.MAGIC, PrayerClassifier.styleOf(Prayer.AUGURY));
		assertEquals(CombatStyle.MAGIC, PrayerClassifier.styleOf(Prayer.MYSTIC_MIGHT));
	}

	@Test
	public void styleOfReturnsNullForRuinousAndNonOffensePrayers()
	{
		// No verified style pairing for Ruinous Powers offense prayers — never flagged.
		assertNull(PrayerClassifier.styleOf(Prayer.RP_DECIMATE));
		assertNull(PrayerClassifier.styleOf(Prayer.RP_ANCIENT_SIGHT));
		assertNull(PrayerClassifier.styleOf(Prayer.STEEL_SKIN));
		assertNull(PrayerClassifier.styleOf(Prayer.PROTECT_FROM_MELEE));
	}
}

package com.combatglance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

import net.runelite.api.Prayer;
import net.runelite.api.gameval.SpriteID;
import org.junit.Test;

public class PrayerSpritesTest
{
	@Test
	public void mapsProtectFromMeleeToTheOnSprite()
	{
		assertEquals(SpriteID.Prayeron.PROTECT_FROM_MELEE, PrayerSprites.spriteId(Prayer.PROTECT_FROM_MELEE));
	}

	@Test
	public void nullPrayerUsesGenericOrbSprite()
	{
		assertEquals(SpriteID.OrbIcon.PRAYER, PrayerSprites.spriteId(null));
		assertEquals(SpriteID.OrbIcon.PRAYER, PrayerSprites.GENERIC_SPRITE);
	}

	@Test
	public void shortLabelsFitACardSlot()
	{
		assertEquals("Protect", PrayerSprites.shortLabel(Prayer.PROTECT_FROM_MELEE));
		assertEquals("Protect", PrayerSprites.shortLabel(Prayer.PROTECT_FROM_MISSILES));
		assertEquals("Protect", PrayerSprites.shortLabel(Prayer.PROTECT_FROM_MAGIC));
		assertEquals("Piety", PrayerSprites.shortLabel(Prayer.PIETY));
		assertEquals("Rigour", PrayerSprites.shortLabel(Prayer.RIGOUR));
		assertEquals("Augury", PrayerSprites.shortLabel(Prayer.AUGURY));
		assertEquals("Dampen", PrayerSprites.shortLabel(Prayer.RP_DAMPEN_MELEE));
		assertEquals("None", PrayerSprites.shortLabel(null));
		for (Prayer prayer : Prayer.values())
		{
			assertNotNull(PrayerSprites.shortLabel(prayer));
		}
	}
}

package com.combatglance;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

public class AttackAnimationsTest
{
	@Test
	public void recognizesMeleeRangedAndMagicAttackAnimations()
	{
		assertTrue(AttackAnimations.isAttack(AnimationID.HUMAN_SWORD_SLASH));
		assertTrue(AttackAnimations.isAttack(AnimationID.SLAYER_ABYSSAL_WHIP_ATTACK));
		assertTrue(AttackAnimations.isAttack(AnimationID.HUMAN_BOW));
		assertTrue(AttackAnimations.isAttack(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK));
		assertTrue(AttackAnimations.isAttack(AnimationID.HUMAN_CASTSTRIKE_STAFF_WALKMERGE));
	}

	@Test
	public void rejectsNonAttackAnimations()
	{
		assertFalse(AttackAnimations.isAttack(AnimationID.HUMAN_EAT));
		assertFalse(AttackAnimations.isAttack(AnimationID.HUMAN_FLETCHING));
	}

	@Test
	public void rejectsNoneAndNegativeAnimation()
	{
		assertFalse(AttackAnimations.isAttack(-1));
	}
}

package com.combatglance;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import net.runelite.api.Prayer;
import org.junit.Test;

public class CombatGlanceSnapshotTest
{
	@Test
	public void noMismatchWhenOffenseSlotIsEmpty()
	{
		CombatGlanceSnapshot snap = snapshot(CombatStyle.MELEE, null);
		assertFalse(snap.isOffenseStyleMismatch());
	}

	@Test
	public void noMismatchWhenOffenseMatchesStyle()
	{
		CombatGlanceSnapshot snap = snapshot(CombatStyle.MELEE, Prayer.PIETY);
		assertFalse(snap.isOffenseStyleMismatch());
	}

	@Test
	public void mismatchWhenOffenseIsForADifferentStyle()
	{
		CombatGlanceSnapshot snap = snapshot(CombatStyle.MELEE, Prayer.RIGOUR);
		assertTrue(snap.isOffenseStyleMismatch());
	}

	@Test
	public void ruinousOffensePrayersAreNeverFlaggedMismatched()
	{
		CombatGlanceSnapshot snap = snapshot(CombatStyle.MELEE, Prayer.RP_DECIMATE);
		assertFalse(snap.isOffenseStyleMismatch());
	}

	@Test
	public void attackTimerUnknownByDefault()
	{
		CombatGlanceSnapshot snap = snapshot(CombatStyle.MELEE, null);
		assertFalse(snap.isAttackTimerKnown());
	}

	@Test
	public void attackTimerKnownWhenBothFieldsAreNonNegative()
	{
		CombatGlanceSnapshot snap = new CombatGlanceSnapshot(
			true, CombatStyle.MELEE, null, null, -1, -1, Collections.emptyList(), false, 2, 0.5);
		assertTrue(snap.isAttackTimerKnown());
	}

	private static CombatGlanceSnapshot snapshot(CombatStyle style, Prayer offense)
	{
		return new CombatGlanceSnapshot(
			true, style, offense, null, -1, -1, Collections.emptyList(), false, -1, -1);
	}
}

package com.combatglance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import org.junit.Test;

/**
 * {@link CombatGlanceState} refresh path, exercised against a minimal JDK-only fake
 * {@link Client} (see {@link #fakeClient}) rather than a mocking library — {@code Client} is a
 * huge interface, and the implementation brief explicitly prefers this over "brittle Mockito
 * theater." Weapon-style resolution itself is covered in isolation by {@link CombatStyleTest};
 * this class focuses on snapshot/reset behavior and prayer sampling.
 */
public class CombatGlanceStateTest
{
	@Test
	public void initialSnapshotIsLoggedOut()
	{
		CombatGlanceState state = new CombatGlanceState();
		assertFalse(state.snapshot().isLoggedIn());
		assertNull(state.snapshot().getOffensivePrayer());
		assertNull(state.snapshot().getOverheadPrayer());
	}

	@Test
	public void refreshWhenNotLoggedInResetsSnapshot()
	{
		CombatGlanceState state = new CombatGlanceState();
		Client client = fakeClient(GameState.LOGIN_SCREEN, EnumSet.noneOf(Prayer.class));

		state.refresh(client, false);

		assertFalse(state.snapshot().isLoggedIn());
		assertEquals("not-logged-in", state.getLastResetReason());
	}

	@Test
	public void refreshSamplesActivePrayersIntoOffenseAndOverheadSlots()
	{
		CombatGlanceState state = new CombatGlanceState();
		Client client = fakeClient(GameState.LOGGED_IN, EnumSet.of(Prayer.PIETY, Prayer.PROTECT_FROM_MELEE));

		state.refresh(client, false);

		CombatGlanceSnapshot snap = state.snapshot();
		assertTrue(snap.isLoggedIn());
		assertEquals(Prayer.PIETY, snap.getOffensivePrayer());
		assertEquals(Prayer.PROTECT_FROM_MELEE, snap.getOverheadPrayer());
	}

	@Test
	public void refreshWithNoActivePrayersLeavesSlotsEmpty()
	{
		CombatGlanceState state = new CombatGlanceState();
		Client client = fakeClient(GameState.LOGGED_IN, EnumSet.noneOf(Prayer.class));

		state.refresh(client, false);

		CombatGlanceSnapshot snap = state.snapshot();
		assertTrue(snap.isLoggedIn());
		assertNull(snap.getOffensivePrayer());
		assertNull(snap.getOverheadPrayer());
	}

	@Test
	public void resetClearsPrayersAndLoggedInFlag()
	{
		CombatGlanceState state = new CombatGlanceState();
		Client client = fakeClient(GameState.LOGGED_IN, EnumSet.of(Prayer.PIETY, Prayer.PROTECT_FROM_MELEE));
		state.refresh(client, false);
		assertTrue(state.snapshot().isLoggedIn());

		state.reset("test-reset");

		CombatGlanceSnapshot snap = state.snapshot();
		assertFalse(snap.isLoggedIn());
		assertNull(snap.getOffensivePrayer());
		assertNull(snap.getOverheadPrayer());
		assertEquals("test-reset", state.getLastResetReason());
	}

	@Test
	public void debugActivePrayerListIsUnmodifiableAndOnlyPopulatedWhenRequested()
	{
		CombatGlanceState state = new CombatGlanceState();
		Client client = fakeClient(GameState.LOGGED_IN, EnumSet.of(Prayer.PIETY));

		state.refresh(client, false);
		assertTrue(state.snapshot().getDebugActivePrayers().isEmpty());

		state.refresh(client, true);
		assertEquals(1, state.snapshot().getDebugActivePrayers().size());
		try
		{
			state.snapshot().getDebugActivePrayers().add(Prayer.RIGOUR);
			fail("expected UnsupportedOperationException");
		}
		catch (UnsupportedOperationException expected)
		{
			// list must stay unmodifiable — the overlay must never be able to mutate state
		}
	}

	/**
	 * Minimal JDK-only fake. Unconfigured methods return benign zero-value defaults so calls
	 * this test doesn't care about (weapon/style enum lookups) don't throw — CombatStyleResolver
	 * already catches that and falls back to MELEE, which these tests treat as an acceptable,
	 * honest default.
	 */
	private static Client fakeClient(GameState gameState, Set<Prayer> activePrayers)
	{
		Player player = (Player) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[]{Player.class},
			(proxy, method, args) -> defaultValue(method.getReturnType()));

		Map<String, Object> answers = new HashMap<>();
		answers.put("getGameState", gameState);
		answers.put("getLocalPlayer", gameState == GameState.LOGGED_IN ? player : null);

		InvocationHandler handler = (proxy, method, args) ->
		{
			if ("isPrayerActive".equals(method.getName()) && args != null && args.length == 1)
			{
				return activePrayers.contains(args[0]);
			}
			if (answers.containsKey(method.getName()))
			{
				return answers.get(method.getName());
			}
			return defaultValue(method.getReturnType());
		};
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, handler);
	}

	private static Object defaultValue(Class<?> returnType)
	{
		if (returnType == void.class || !returnType.isPrimitive())
		{
			return null;
		}
		if (returnType == boolean.class)
		{
			return Boolean.FALSE;
		}
		if (returnType == byte.class)
		{
			return (byte) 0;
		}
		if (returnType == short.class)
		{
			return (short) 0;
		}
		if (returnType == long.class)
		{
			return 0L;
		}
		if (returnType == float.class)
		{
			return 0f;
		}
		if (returnType == double.class)
		{
			return 0d;
		}
		if (returnType == char.class)
		{
			return (char) 0;
		}
		return 0;
	}
}

