package com.combatglance;

import javax.annotation.Nullable;

/**
 * Attack-cycle model powering the optional, off-by-default attack-timer bar (overview §5.2/§9.4,
 * implementation brief §4.2/§9.3).
 *
 * <p><b>Design (rewritten after QA — read this before changing the logic again):</b> the first
 * version required a fresh, correctly-timed observation of every single attack to keep the bar
 * showing, ported from TickFlow's rolling-timeline tracker. That's the wrong shape for this
 * plugin: animation events don't reliably fire once per attack (many weapons don't return to an
 * idle animation between swings, so {@code AnimationChanged} simply doesn't re-fire), and a
 * single observation that didn't match the previous prediction nuked all learned state back to
 * "unknown" — so in practice the bar stayed hidden for most of a fight.
 *
 * <p>This version needs an attack-speed value and exactly one anchor point (when combat with the
 * current target began), then free-runs the cycle every {@code speedTicks} ticks from there —
 * pure tick arithmetic, no drift, no per-attack reconfirmation required. An observed attack
 * (best-effort, animation-based) re-anchors to self-correct any phase error when it does arrive,
 * but a mistimed or missed observation never discards the known weapon speed and never hides the
 * bar. Precision is intentionally traded for reliability: this is "roughly which part of the
 * swing/cast/cooldown am I in", not a tick-perfect timeline (that's TickFlow).
 */
final class AttackCycleTracker
{
	static final int MIN_SPEED_TICKS = 1;
	static final int MAX_SPEED_TICKS = 10;
	static final int INACTIVITY_TIMEOUT_TICKS = 25;

	private int speedTicks = -1;
	private long anchorTick = -1;
	private long lastActivityTick = -1;
	@Nullable
	private String targetIdentity;

	/**
	 * Apply the equipped weapon's attack speed, or clear it when unknown/out of a sane range.
	 * A genuine change re-anchors on the next engagement rather than carrying over a cycle phase
	 * that belonged to a different weapon's cadence.
	 */
	void setWeaponSpeed(int aspeed)
	{
		int resolved = (aspeed >= MIN_SPEED_TICKS && aspeed <= MAX_SPEED_TICKS) ? aspeed : -1;
		if (resolved != speedTicks)
		{
			speedTicks = resolved;
			anchorTick = -1;
		}
	}

	/**
	 * The player has an interacting target this tick. Establishes an anchor the first tick this
	 * becomes true, and re-anchors cleanly on a target change; otherwise a cheap no-op so it's
	 * safe to call on every refresh, not just once per tick.
	 */
	void noteEngagement(long tickIndex, String target)
	{
		if (!target.equals(targetIdentity))
		{
			targetIdentity = target;
			anchorTick = tickIndex;
		}
		else if (anchorTick < 0)
		{
			anchorTick = tickIndex;
		}
		lastActivityTick = tickIndex;
	}

	/** No interacting target this tick — stop tracking a target identity, but keep the last
	 *  known cadence and anchor until the inactivity timeout actually clears them. */
	void noteDisengaged()
	{
		targetIdentity = null;
	}

	/**
	 * Best-effort attack observation (animation-based; see class javadoc for why this is
	 * corroboration only, not the sole source of truth). Re-anchors to the observed tick when a
	 * speed is already known; otherwise ignored — never invents timing from nothing.
	 */
	void onAttackObserved(long tickIndex)
	{
		if (speedTicks <= 0)
		{
			return;
		}
		anchorTick = tickIndex;
		lastActivityTick = tickIndex;
	}

	/** @return {@code true} if the tracker was cleared due to inactivity */
	boolean onTick(long tickIndex)
	{
		if (lastActivityTick >= 0 && tickIndex - lastActivityTick >= INACTIVITY_TIMEOUT_TICKS)
		{
			anchorTick = -1;
			lastActivityTick = -1;
			targetIdentity = null;
			return true;
		}
		return false;
	}

	boolean isKnown()
	{
		return speedTicks > 0 && anchorTick >= 0;
	}

	/**
	 * Ticks remaining until ready, or -1 when not known — never a guess. 0 means ready now, i.e.
	 * this is the last tick of the wait — matches {@link #elapsedFraction} reading 1.0 (full bar)
	 * on that same tick; see that method's javadoc for why the current tick counts as fully
	 * elapsed rather than just-started.
	 */
	int ticksUntilReady(long tickIndex)
	{
		if (!isKnown())
		{
			return -1;
		}
		long intoCycle = Math.floorMod(tickIndex - anchorTick, speedTicks);
		return (int) (speedTicks - 1 - intoCycle);
	}

	/**
	 * Fraction of the current cycle elapsed, in {@code (0, 1]}, for the bar sweep. -1 when
	 * unknown. The tick a game tick is currently on counts as fully elapsed for that whole tick's
	 * ~0.6s render duration — i.e. {@code intoCycle} is 1-indexed, not 0-indexed — so the last
	 * waiting tick reads 1.0 (bar completely full) for its entire duration rather than only for a
	 * single boundary instant that's immediately overwritten by the next re-anchor. A 0-indexed
	 * fraction (the first version of this method) tops out at {@code (speedTicks-1)/speedTicks}
	 * and never visibly reaches the end of the bar — exactly the "ends just before the end of the
	 * bar" bug this was rewritten to fix.
	 */
	double elapsedFraction(long tickIndex)
	{
		if (!isKnown())
		{
			return -1;
		}
		long intoCycle = Math.floorMod(tickIndex - anchorTick, speedTicks);
		return (intoCycle + 1) / (double) speedTicks;
	}

	/** Full reset — logout, hop, death, plugin disable. Clears the known weapon speed too. */
	void reset()
	{
		speedTicks = -1;
		anchorTick = -1;
		lastActivityTick = -1;
		targetIdentity = null;
	}
}

package com.combatglance;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Combat Glance — passive PvM readout of current attack type, offensive prayer, and overhead
 * prayer. Observation only: never clicks, prays, or recommends anything (see product overview).
 *
 * <p>Event mapping:
 * <ul>
 *   <li>{@link GameTick} — stamps the tick-start time for the optional tick-track bar, advances
 *       the attack-cycle tick clock, then a periodic full refresh; the authoritative backstop</li>
 *   <li>{@link VarbitChanged} — immediate refresh on weapon-category / style / autocast /
 *       any individual prayer varbit, so overhead flicks and style swaps don't wait a tick</li>
 *   <li>{@link ItemContainerChanged} (worn equipment) — immediate refresh after a weapon swap,
 *       plus re-resolving weapon attack speed for the optional attack-timer bar</li>
 *   <li>{@link GameStateChanged} — reset/hide on login screen, hopping, connection loss,
 *       loading; refresh once loading finishes into {@code LOGGED_IN}</li>
 *   <li>{@link ActorDeath} (local player) — refresh; prayers deactivate on death, so this just
 *       reflects that promptly rather than waiting for the next tick</li>
 *   <li>{@link AnimationChanged} (local player) — best-effort attack observation for the
 *       optional, off-by-default attack-timer bar only (corroboration/drift-correction, not the
 *       sole trigger — see {@link AttackCycleTracker}); never affects the offense/defense
 *       prayer or style slots</li>
 *   <li>{@link ConfigChanged} — when {@code showAttackTimer} turns on, immediately resolves the
 *       currently equipped weapon's attack speed rather than waiting for the next weapon swap
 *       (otherwise the bar could stay hidden all session if toggled on with a weapon already
 *       equipped from before); also starts/stops/adjusts the optional tick sound</li>
 * </ul>
 *
 * <p>Optional tick sound: same {@link TickMetronome} sound-generation logic as TickFlow, but
 * unlike TickFlow there are no mute/volume buttons drawn on the overlay — {@code tickSound} and
 * {@code tickSoundVolume} are config-panel-only settings, so the card stays a passive readout.
 */
@Slf4j
@PluginDescriptor(
	name = "Combat Glance",
	description = "Shows your current attack style, offensive prayer, and overhead prayer for PvM.",
	tags = {"pvm", "combat", "prayer", "melee", "ranged", "magic", "overhead", "overlay"}
)
public class CombatGlancePlugin extends Plugin
{
	private static final Set<GameState> RESET_STATES;
	/**
	 * Sorted, checked via {@link Arrays#binarySearch}, not a {@code Set<Integer>}: {@code
	 * VarbitChanged} fires very frequently for varbits that have nothing to do with this plugin
	 * (minimap state, run energy, interface widgets, ...), and a boxed-Integer HashSet lookup
	 * would allocate on every single one of those just to say "no". A sorted primitive array
	 * avoids that entirely.
	 */
	private static final int[] PRAYER_VARBITS;

	static
	{
		RESET_STATES = new HashSet<>();
		RESET_STATES.add(GameState.LOGIN_SCREEN);
		RESET_STATES.add(GameState.LOGIN_SCREEN_AUTHENTICATOR);
		RESET_STATES.add(GameState.LOGGING_IN);
		RESET_STATES.add(GameState.HOPPING);
		RESET_STATES.add(GameState.CONNECTION_LOST);
		RESET_STATES.add(GameState.LOADING);

		Prayer[] prayers = Prayer.values();
		PRAYER_VARBITS = new int[prayers.length];
		for (int i = 0; i < prayers.length; i++)
		{
			PRAYER_VARBITS[i] = prayers[i].getVarbit();
		}
		Arrays.sort(PRAYER_VARBITS);
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CombatGlanceConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CombatGlanceOverlay overlay;

	@Inject
	private CombatGlanceIcons icons;

	@Inject
	private ItemManager itemManager;

	@Inject
	private TickMetronome metronome;

	private final CombatGlanceState state = new CombatGlanceState();

	private int cachedWeaponId = -1;
	private volatile long lastGameTickMs;

	@Provides
	CombatGlanceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CombatGlanceConfig.class);
	}

	@Override
	protected void startUp()
	{
		state.reset("startup");
		resetEquipmentCache();
		overlayManager.add(overlay);
		metronome.setVolumePercent(config.tickSoundVolume());
		if (config.tickSound())
		{
			metronome.start();
		}
		// Plugin list toggles startUp on the EDT — never touch the client there.
		clientThread.invoke(() ->
		{
			refreshIfLoggedIn();
			refreshEquipmentCache();
		});
		log.debug("Combat Glance started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		icons.clear();
		state.reset("shutdown");
		resetEquipmentCache();
		lastGameTickMs = 0L;
		metronome.stop();
		log.debug("Combat Glance stopped");
	}

	CombatGlanceSnapshot getSnapshot()
	{
		return state.snapshot();
	}

	/**
	 * Progress through the current game tick in {@code [0, 1]}, for the optional tick-track bar
	 * (§9.4 — a generic tick heartbeat, unrelated to attack readiness). Safe to call from render.
	 */
	double getTickProgress()
	{
		if (lastGameTickMs <= 0L)
		{
			return 0;
		}
		long elapsed = System.currentTimeMillis() - lastGameTickMs;
		if (elapsed <= 0)
		{
			return 0;
		}
		if (elapsed >= Constants.GAME_TICK_LENGTH)
		{
			return 1;
		}
		return elapsed / (double) Constants.GAME_TICK_LENGTH;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		lastGameTickMs = System.currentTimeMillis();
		if (config.tickSound())
		{
			metronome.play();
		}
		state.onGameTick();
		refreshIfLoggedIn();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.COM_MODE
			|| event.getVarbitId() == VarbitID.COMBAT_WEAPON_CATEGORY
			|| event.getVarbitId() == VarbitID.AUTOCAST_DEFMODE
			|| Arrays.binarySearch(PRAYER_VARBITS, event.getVarbitId()) >= 0)
		{
			refreshIfLoggedIn();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			refreshEquipmentCache();
			refreshIfLoggedIn();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (RESET_STATES.contains(gameState))
		{
			state.reset("game-state:" + gameState);
			resetEquipmentCache();
			lastGameTickMs = 0L;
		}
		else if (gameState == GameState.LOGGED_IN)
		{
			refreshEquipmentCache();
			refreshIfLoggedIn();
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Player local = client.getLocalPlayer();
		if (local != null && event.getActor() == local)
		{
			// Prayers deactivate on death; refresh promptly rather than waiting for the next tick.
			refreshIfLoggedIn();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CombatGlanceConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("showAttackTimer".equals(event.getKey()))
		{
			// Weapon attack speed is normally only (re-)resolved on an actual weapon swap. If the
			// player enables this toggle mid-session with a weapon already equipped since before —
			// the common case — nothing would ever push that weapon's known speed into the
			// tracker until the next swap. Resolve it immediately instead of waiting.
			if (config.showAttackTimer())
			{
				clientThread.invoke(() -> state.onWeaponSpeedResolved(resolveWeaponAspeed(cachedWeaponId)));
			}
		}
		else if ("tickSound".equals(event.getKey()))
		{
			if (config.tickSound())
			{
				metronome.start();
			}
			else
			{
				metronome.stop();
			}
		}
		else if ("tickSoundVolume".equals(event.getKey()))
		{
			metronome.setVolumePercent(config.tickSoundVolume());
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!config.showAttackTimer())
		{
			return;
		}
		Actor actor = event.getActor();
		Player local = client.getLocalPlayer();
		if (local == null || actor != local)
		{
			return;
		}
		if (local.getInteracting() != null && AttackAnimations.isAttack(local.getAnimation()))
		{
			state.onAttackObserved();
		}
	}

	private void refreshIfLoggedIn()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			state.refresh(client, config.debugMode());
		}
	}

	private void resetEquipmentCache()
	{
		cachedWeaponId = -1;
	}

	/**
	 * Re-resolve the equipped weapon's attack speed for the optional attack-timer bar when the
	 * weapon actually changes. Only the weapon id matters here — shield/ammo swaps don't affect
	 * attack cadence, so unlike an earlier version of this method, they're not tracked at all.
	 * No-op-safe to call often.
	 */
	private void refreshEquipmentCache()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		int weaponId = equipment == null ? -1 : itemId(equipment.getItems(), EquipmentInventorySlot.WEAPON);
		if (weaponId == cachedWeaponId)
		{
			return;
		}
		cachedWeaponId = weaponId;
		state.onWeaponSpeedResolved(resolveWeaponAspeed(weaponId));
	}

	private int resolveWeaponAspeed(int weaponId)
	{
		if (weaponId <= 0)
		{
			return -1;
		}
		ItemStats stats = itemManager.getItemStats(weaponId);
		if (stats == null)
		{
			return -1;
		}
		ItemEquipmentStats equipmentStats = stats.getEquipment();
		if (equipmentStats == null)
		{
			return -1;
		}
		return equipmentStats.getAspeed();
	}

	private static int itemId(Item[] items, EquipmentInventorySlot slot)
	{
		int idx = slot.getSlotIdx();
		if (items == null || idx < 0 || idx >= items.length || items[idx] == null)
		{
			return -1;
		}
		return items[idx].getId();
	}
}

package com.combatglance;

import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ParamID;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Resolves the player's current combat skill family from the equipped weapon category and
 * selected attack style — the same client enums the core Attack Styles plugin uses.
 *
 * <p>Never returns a recommendation. Unknown or exotic weapons fall back to MELEE, the honest
 * conservative default (matches unarmed), rather than guessing MAGIC or RANGED.
 */
final class CombatStyleResolver
{
	private CombatStyleResolver()
	{
	}

	static CombatStyle resolve(Client client)
	{
		try
		{
			int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
			int styleIndex = client.getVarpValue(VarPlayerID.COM_MODE);
			int castingMode = client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
			String styleName = styleNameAt(client, weaponType, styleIndex, castingMode);
			if (styleName != null)
			{
				return CombatStyle.fromAttackStyleName(styleName);
			}
		}
		catch (Exception ignored)
		{
			// Prefer the conservative melee default over crashing the overlay when enums are unavailable.
		}
		return CombatStyle.MELEE;
	}

	@Nullable
	private static String styleNameAt(Client client, int weaponType, int attackStyleIndex, int castingMode)
	{
		String[] names = weaponTypeStyleNames(client, weaponType);
		if (names.length == 0)
		{
			return null;
		}
		int index = attackStyleIndex;
		// Staff defensive casting uses slot 4 + casting-mode offset (script 4525).
		if (index == 4)
		{
			index += castingMode;
		}
		if (index < 0 || index >= names.length)
		{
			return null;
		}
		return names[index];
	}

	private static String[] weaponTypeStyleNames(Client client, int weaponType)
	{
		EnumComposition weaponStyles = client.getEnum(EnumID.WEAPON_STYLES);
		int weaponStyleEnum = weaponStyles.getIntValue(weaponType);
		if (weaponStyleEnum == -1)
		{
			return fallbackStyleNames(weaponType);
		}

		int[] structs = client.getEnum(weaponStyleEnum).getIntVals();
		String[] names = new String[structs.length];
		for (int i = 0; i < structs.length; i++)
		{
			StructComposition styleStruct = client.getStructComposition(structs[i]);
			String name = styleStruct.getStringValue(ParamID.ATTACK_STYLE_NAME);
			// Slot 5 "Defensive" on casting weapons is defensive casting.
			if (i == 5 && name != null && "Defensive".equalsIgnoreCase(name))
			{
				names[i] = "Defensive casting";
			}
			else
			{
				names[i] = name;
			}
		}
		return names;
	}

	/**
	 * Hard-coded fallbacks for weapon categories missing from {@link EnumID#WEAPON_STYLES}.
	 */
	private static String[] fallbackStyleNames(int weaponType)
	{
		if (weaponType == 22)
		{
			// Blue moon spear
			return new String[]{"Accurate", "Aggressive", null, "Defensive", "Casting", "Defensive casting"};
		}
		if (weaponType == 30)
		{
			// Partisan
			return new String[]{"Accurate", "Aggressive", "Aggressive", "Defensive"};
		}
		return new String[0];
	}
}

package com.combatglance;

import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.Prayer;

/**
 * Pure, allowlisted mapping from {@link Prayer} to {@link PrayerKind}, plus deterministic
 * "which one goes on the card" selection when several prayers of the same kind are active.
 *
 * <p>Classification is a fixed allowlist, never a name/string match: a future prayer the API
 * adds that isn't listed here classifies as {@link PrayerKind#OTHER} and stays off the card
 * (see overview §10 — explicit allowlist, not a fuzzy guess).
 */
final class PrayerClassifier
{
	private static final Map<Prayer, PrayerKind> KIND = new EnumMap<>(Prayer.class);

	static
	{
		// OVERHEAD — standard book.
		KIND.put(Prayer.PROTECT_FROM_MAGIC, PrayerKind.OVERHEAD);
		KIND.put(Prayer.PROTECT_FROM_MISSILES, PrayerKind.OVERHEAD);
		KIND.put(Prayer.PROTECT_FROM_MELEE, PrayerKind.OVERHEAD);
		KIND.put(Prayer.RETRIBUTION, PrayerKind.OVERHEAD);
		KIND.put(Prayer.REDEMPTION, PrayerKind.OVERHEAD);
		KIND.put(Prayer.SMITE, PrayerKind.OVERHEAD);

		// OVERHEAD — Ruinous Powers.
		KIND.put(Prayer.RP_DAMPEN_MAGIC, PrayerKind.OVERHEAD);
		KIND.put(Prayer.RP_DAMPEN_RANGED, PrayerKind.OVERHEAD);
		KIND.put(Prayer.RP_DAMPEN_MELEE, PrayerKind.OVERHEAD);
		KIND.put(Prayer.RP_WRATH, PrayerKind.OVERHEAD);

		// OFFENSE — combined / high-tier.
		KIND.put(Prayer.PIETY, PrayerKind.OFFENSE);
		KIND.put(Prayer.CHIVALRY, PrayerKind.OFFENSE);
		KIND.put(Prayer.RIGOUR, PrayerKind.OFFENSE);
		KIND.put(Prayer.AUGURY, PrayerKind.OFFENSE);
		KIND.put(Prayer.DEADEYE, PrayerKind.OFFENSE);
		KIND.put(Prayer.MYSTIC_VIGOUR, PrayerKind.OFFENSE);

		// OFFENSE — single-skill style prayers.
		KIND.put(Prayer.BURST_OF_STRENGTH, PrayerKind.OFFENSE);
		KIND.put(Prayer.SUPERHUMAN_STRENGTH, PrayerKind.OFFENSE);
		KIND.put(Prayer.ULTIMATE_STRENGTH, PrayerKind.OFFENSE);
		KIND.put(Prayer.CLARITY_OF_THOUGHT, PrayerKind.OFFENSE);
		KIND.put(Prayer.IMPROVED_REFLEXES, PrayerKind.OFFENSE);
		KIND.put(Prayer.INCREDIBLE_REFLEXES, PrayerKind.OFFENSE);
		KIND.put(Prayer.SHARP_EYE, PrayerKind.OFFENSE);
		KIND.put(Prayer.HAWK_EYE, PrayerKind.OFFENSE);
		KIND.put(Prayer.EAGLE_EYE, PrayerKind.OFFENSE);
		KIND.put(Prayer.MYSTIC_WILL, PrayerKind.OFFENSE);
		KIND.put(Prayer.MYSTIC_LORE, PrayerKind.OFFENSE);
		KIND.put(Prayer.MYSTIC_MIGHT, PrayerKind.OFFENSE);

		// OFFENSE — Ruinous Powers. Style-priority chains below only cover the standard book;
		// these classify as OFFENSE but fall through to the enum-order tie-break (step 4), since
		// Ruinous Powers replaces the standard book entirely and can never be active alongside it
		// in real play — an explicit style pairing here would be an unverified guess, not a fact.
		KIND.put(Prayer.RP_ANCIENT_STRENGTH, PrayerKind.OFFENSE);
		KIND.put(Prayer.RP_ANCIENT_SIGHT, PrayerKind.OFFENSE);
		KIND.put(Prayer.RP_ANCIENT_WILL, PrayerKind.OFFENSE);
		KIND.put(Prayer.RP_DECIMATE, PrayerKind.OFFENSE);
		KIND.put(Prayer.RP_ANNIHILATE, PrayerKind.OFFENSE);
		KIND.put(Prayer.RP_VAPORISE, PrayerKind.OFFENSE);

		// Everything else defaults to OTHER (see kindOf) — skin prayers, restores, Protect Item,
		// vows, and any prayer the API adds that isn't explicitly listed above.
	}

	/** Style-specific priority chain, highest preference first. Standard book only — see above. */
	private static final Prayer[] MELEE_PRIORITY = {
		Prayer.PIETY, Prayer.CHIVALRY,
		Prayer.ULTIMATE_STRENGTH, Prayer.INCREDIBLE_REFLEXES,
		Prayer.SUPERHUMAN_STRENGTH, Prayer.IMPROVED_REFLEXES,
		Prayer.BURST_OF_STRENGTH, Prayer.CLARITY_OF_THOUGHT,
	};
	private static final Prayer[] RANGED_PRIORITY = {
		Prayer.RIGOUR, Prayer.DEADEYE, Prayer.EAGLE_EYE, Prayer.HAWK_EYE, Prayer.SHARP_EYE,
	};
	private static final Prayer[] MAGIC_PRIORITY = {
		Prayer.AUGURY, Prayer.MYSTIC_VIGOUR, Prayer.MYSTIC_MIGHT, Prayer.MYSTIC_LORE, Prayer.MYSTIC_WILL,
	};
	/** Step 2: any remaining combined prayer, checked regardless of current style. */
	private static final Prayer[] COMBINED_FALLBACK = {
		Prayer.PIETY, Prayer.CHIVALRY, Prayer.RIGOUR, Prayer.AUGURY,
	};

	private PrayerClassifier()
	{
	}

	static PrayerKind kindOf(Prayer prayer)
	{
		PrayerKind kind = KIND.get(prayer);
		return kind != null ? kind : PrayerKind.OTHER;
	}

	/**
	 * Deterministic primary offensive prayer when several {@link PrayerKind#OFFENSE} prayers are
	 * active at once. Priority (documented in the overview/implementation brief):
	 * <ol>
	 *   <li>The combined/style-matching prayer chain for the current {@link CombatStyle}</li>
	 *   <li>Any remaining combined prayer (Piety / Chivalry / Rigour / Augury)</li>
	 *   <li>(covered by 1 above for the active style) any style-matching single-skill prayer</li>
	 *   <li>Any other active OFFENSE prayer, stable enum-order tie-break</li>
	 * </ol>
	 */
	@Nullable
	static Prayer primaryOffense(Set<Prayer> active, CombatStyle style)
	{
		if (active.isEmpty())
		{
			return null;
		}

		Prayer[] styleChain = styleChain(style);
		for (Prayer candidate : styleChain)
		{
			if (active.contains(candidate))
			{
				return candidate;
			}
		}
		for (Prayer candidate : COMBINED_FALLBACK)
		{
			if (active.contains(candidate))
			{
				return candidate;
			}
		}
		for (Prayer prayer : Prayer.values())
		{
			if (active.contains(prayer) && kindOf(prayer) == PrayerKind.OFFENSE)
			{
				return prayer;
			}
		}
		return null;
	}

	/**
	 * The single active overhead prayer, or null. Only one overhead can be active in normal
	 * play; if the client somehow reports more than one, pick by stable enum order.
	 */
	@Nullable
	static Prayer primaryOverhead(Set<Prayer> active)
	{
		for (Prayer prayer : Prayer.values())
		{
			if (active.contains(prayer) && kindOf(prayer) == PrayerKind.OVERHEAD)
			{
				return prayer;
			}
		}
		return null;
	}

	private static Prayer[] styleChain(CombatStyle style)
	{
		if (style == CombatStyle.RANGED)
		{
			return RANGED_PRIORITY;
		}
		if (style == CombatStyle.MAGIC)
		{
			return MAGIC_PRIORITY;
		}
		return MELEE_PRIORITY;
	}

	/**
	 * The single {@link CombatStyle} an OFFENSE prayer is designed for, or null when there is no
	 * verified single-style pairing. Used only for the optional, off-by-default mismatch
	 * highlight (overview §5.3/§7.2 exception) — never for prayer selection itself.
	 *
	 * <p>Ruinous Powers offense prayers deliberately return null here, for the same reason they
	 * are absent from the style-priority chains above: no verified style pairing, so they are
	 * never flagged as mismatched rather than risk a wrong guess.
	 */
	@Nullable
	static CombatStyle styleOf(Prayer prayer)
	{
		switch (prayer)
		{
			case BURST_OF_STRENGTH:
			case SUPERHUMAN_STRENGTH:
			case ULTIMATE_STRENGTH:
			case CLARITY_OF_THOUGHT:
			case IMPROVED_REFLEXES:
			case INCREDIBLE_REFLEXES:
			case CHIVALRY:
			case PIETY:
				return CombatStyle.MELEE;
			case SHARP_EYE:
			case HAWK_EYE:
			case EAGLE_EYE:
			case DEADEYE:
			case RIGOUR:
				return CombatStyle.RANGED;
			case MYSTIC_WILL:
			case MYSTIC_LORE:
			case MYSTIC_MIGHT:
			case MYSTIC_VIGOUR:
			case AUGURY:
				return CombatStyle.MAGIC;
			default:
				return null;
		}
	}
}

package com.combatglance;

import java.util.Arrays;
import net.runelite.api.gameval.AnimationID;

/**
 * Bounded, hand-curated allowlist of the local player's animation IDs that represent a genuine
 * attack swing/shot/cast — melee, ranged, and magic combined, since {@link AttackCycleTracker}
 * only needs "was that an attack" (re-anchor the cycle), not which combat style it was (the
 * style cell already gets that from {@link CombatStyleResolver}).
 *
 * <p>Same philosophy as {@link PrayerClassifier}: an explicit, documented list beats a guess.
 * The naive {@code animation > 0} check this replaced fired on eating, fletching, emotes, and
 * every other idle animation while in combat, which is what made the old attack-timer bar
 * re-anchor on the wrong ticks. This list is not exhaustive — it deliberately covers the common
 * weapon categories (generic melee stances, bows/crossbows/blowpipe/thrown ammo, standard-book
 * spellcasting) rather than every special-attack and boss-specific animation in the game, mirroring
 * the scope of the reference implementation this was checked against (ngraves95/attacktimer,
 * {@code AnimationData.java}). A missed animation just means one fewer re-anchor opportunity —
 * {@link AttackCycleTracker}'s free-running cycle keeps the bar showing regardless (see its
 * class javadoc), so under-covering here is safe; the list only needs to be broad enough that
 * most attacks get a fresh, precise re-anchor.
 */
final class AttackAnimations
{
	private static final int[] IDS;

	static
	{
		int[] ids = {
			// Melee — generic weapon-stance animations shared across the vast majority of
			// melee weapons (scimitars, swords, axes, maces, spears, whips, staves used to
			// melee, unarmed).
			AnimationID.HUMAN_UNARMEDPUNCH,
			AnimationID.HUMAN_UNARMEDKICK,
			AnimationID.HUMAN_SWORD_SLASH,
			AnimationID.HUMAN_SWORD_STAB,
			AnimationID.HUMAN_AXE_CHOP,
			AnimationID.HUMAN_AXE_HACK,
			AnimationID.HUMAN_BLUNT_POUND,
			AnimationID.HUMAN_BLUNT_SPIKE,
			AnimationID.HUMAN_DHSWORD_SLASH,
			AnimationID.HUMAN_DHSWORD_CHOP,
			AnimationID.HUMAN_DDAGGER_LUNGE,
			AnimationID.HUMAN_KNIFE_CHOP,
			AnimationID.HUMAN_KNIFE_SLASH,
			AnimationID.HUMAN_SPEAR_SPIKE,
			AnimationID.HUMAN_SPEAR_LUNGE,
			AnimationID.HUMAN_SCYTHE_SWEEP,
			AnimationID.HUMAN_STAFF_PUMMEL,
			AnimationID.HUMAN_STAFFORB_PUMMEL,
			AnimationID.HUMAN_CROSSBOW,
			AnimationID.SLAYER_ABYSSAL_WHIP_ATTACK,

			// Ranged — bows, crossbows, blowpipe, thrown ammo, ballista.
			AnimationID.HUMAN_BOW,
			AnimationID.XBOWS_HUMAN_FIRE_AND_RELOAD,
			AnimationID.XBOWS_HUMAN_FIRE_AND_RELOAD_PVN,
			AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK,
			AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK_ORNAMENT,
			AnimationID.HUMAN_STAKE2,
			AnimationID.HUMAN_STAKE2_PVN,
			AnimationID.II_HUMAN_DART_THROW,
			AnimationID.II_HUMAN_DART_THROW_PVN,
			AnimationID.BALLISTA_ATTACK,
			AnimationID.BALLISTA_ATTACK_PVN,

			// Magic — standard spellbook combat casts (god spells, strike/bolt/blast, wave, surge),
			// both bare-handed and staff variants.
			AnimationID.HUMAN_CASTING,
			AnimationID.HUMAN_CASTSTRIKE,
			AnimationID.HUMAN_CASTSTRIKE_STAFF,
			AnimationID.HUMAN_CASTSTRIKE_WALKMERGE,
			AnimationID.HUMAN_CASTSTRIKE_STAFF_WALKMERGE,
			AnimationID.HUMAN_CASTWAVE,
			AnimationID.HUMAN_CASTWAVE_STAFF,
			AnimationID.HUMAN_CASTWAVE_WALKMERGE,
			AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE,
			AnimationID.HUMAN_CAST_SURGE,
			AnimationID.HUMAN_CAST_SURGE_WALKMERGE,
		};
		Arrays.sort(ids);
		IDS = ids;
	}

	private AttackAnimations()
	{
	}

	static boolean isAttack(int animationId)
	{
		return animationId >= 0 && Arrays.binarySearch(IDS, animationId) >= 0;
	}
}

package com.combatglance;

/**
 * Card-relevant classification of a {@link net.runelite.api.Prayer}.
 */
enum PrayerKind
{
	/** Boosts attack, strength, ranged, or magic — eligible for the offense slot. */
	OFFENSE,
	/** Appears over the player's head and protects/reacts in combat — eligible for the defense slot. */
	OVERHEAD,
	/** Everything else (skin prayers, restores, Protect Item, vows, ...). Never shown on the card. */
	OTHER
}

package com.combatglance;

import java.io.ByteArrayInputStream;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Soft synthesized metronome tick — smooth sine with a gentle envelope (not a mechanical click).
 * Playback goes through RuneLite {@link AudioPlayer} (Plugin Hub forbids direct javax.sound use).
 *
 * <p>Same sound-generation logic as TickFlow's {@code TickMetronome} (copied verbatim per
 * implementation brief §1 — approach *and* artifact here, since the whole point is an identical
 * sound). The difference is entirely in how it's controlled: TickFlow adds clickable mute/volume
 * buttons drawn directly on the overlay; Combat Glance deliberately does not — the overlay is
 * meant to stay a calm, passive readout (see overview §7.2), so both {@code tickSound} and
 * {@code tickSoundVolume} live only in the RuneLite config panel, same as every other setting.
 */
@Slf4j
@Singleton
class TickMetronome
{
	private static final float SAMPLE_RATE = 22050f;
	private static final double DURATION_SEC = 0.055;
	private static final double FREQ_HZ = 660.0;
	private static final double PEAK = 0.22;

	private final AudioPlayer audioPlayer;
	private final AtomicBoolean ready = new AtomicBoolean(false);
	private volatile byte[] pcmWav;
	private volatile float gainDb = -10f;

	@Inject
	TickMetronome(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	synchronized void start()
	{
		if (ready.get())
		{
			return;
		}
		pcmWav = buildSoftTickWav();
		ready.set(true);
	}

	synchronized void stop()
	{
		ready.set(false);
		pcmWav = null;
	}

	void setVolumePercent(int percent)
	{
		int clamped = Math.max(5, Math.min(100, percent));
		// Map 5..100% to roughly -24dB .. -2dB (quiet, but floor still audible).
		gainDb = -24f + (clamped - 5) * (22f / 95f);
	}

	void play()
	{
		byte[] wav = pcmWav;
		if (!ready.get() || wav == null)
		{
			return;
		}
		try
		{
			audioPlayer.play(new ByteArrayInputStream(wav), gainDb);
		}
		catch (Exception ex)
		{
			// AudioPlayer may throw IO / sound-line failures; keep tick path quiet.
			log.debug("Tick sound play failed", ex);
		}
	}

	/**
	 * Soft modern blip: sine tone with raised-cosine attack and exponential release.
	 */
	static byte[] buildSoftTickWav()
	{
		int sampleCount = (int) (SAMPLE_RATE * DURATION_SEC);
		byte[] pcm = new byte[sampleCount * 2];
		for (int i = 0; i < sampleCount; i++)
		{
			double t = i / SAMPLE_RATE;
			double env;
			double attack = 0.008;
			double releaseStart = DURATION_SEC * 0.35;
			if (t < attack)
			{
				// Smooth attack (raised cosine)
				env = 0.5 - 0.5 * Math.cos(Math.PI * (t / attack));
			}
			else if (t < releaseStart)
			{
				env = 1.0;
			}
			else
			{
				double u = (t - releaseStart) / (DURATION_SEC - releaseStart);
				env = Math.exp(-3.8 * u) * (1.0 - 0.15 * u);
			}

			// Primary soft tone + quiet lower harmonic for warmth (not buzzy).
			double sample = Math.sin(2 * Math.PI * FREQ_HZ * t) * 0.85
				+ Math.sin(2 * Math.PI * (FREQ_HZ * 0.5) * t) * 0.15;
			sample *= env * PEAK;

			short value = (short) Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, Math.round(sample * Short.MAX_VALUE)));
			pcm[i * 2] = (byte) (value & 0xff);
			pcm[i * 2 + 1] = (byte) ((value >> 8) & 0xff);
		}
		return wrapWav(pcm, (int) SAMPLE_RATE);
	}

	private static byte[] wrapWav(byte[] pcm, int sampleRate)
	{
		int dataSize = pcm.length;
		byte[] wav = new byte[44 + dataSize];
		// RIFF header
		writeAscii(wav, 0, "RIFF");
		writeIntLE(wav, 4, 36 + dataSize);
		writeAscii(wav, 8, "WAVE");
		writeAscii(wav, 12, "fmt ");
		writeIntLE(wav, 16, 16);
		writeShortLE(wav, 20, (short) 1); // PCM
		writeShortLE(wav, 22, (short) 1); // mono
		writeIntLE(wav, 24, sampleRate);
		writeIntLE(wav, 28, sampleRate * 2);
		writeShortLE(wav, 32, (short) 2);
		writeShortLE(wav, 34, (short) 16);
		writeAscii(wav, 36, "data");
		writeIntLE(wav, 40, dataSize);
		System.arraycopy(pcm, 0, wav, 44, dataSize);
		return wav;
	}

	private static void writeAscii(byte[] out, int off, String text)
	{
		for (int i = 0; i < text.length(); i++)
		{
			out[off + i] = (byte) text.charAt(i);
		}
	}

	private static void writeIntLE(byte[] out, int off, int value)
	{
		out[off] = (byte) (value & 0xff);
		out[off + 1] = (byte) ((value >> 8) & 0xff);
		out[off + 2] = (byte) ((value >> 16) & 0xff);
		out[off + 3] = (byte) ((value >> 24) & 0xff);
	}

	private static void writeShortLE(byte[] out, int off, short value)
	{
		out[off] = (byte) (value & 0xff);
		out[off + 1] = (byte) ((value >> 8) & 0xff);
	}
}
